package org.threeten.extra;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

public class TestSeconds_test_parse_CharSequence_valid {

    public static Object[][] data_valid() {
        return new Object[][] {
            // Seconds.
            { "PT0S", 0 },
            { "PT1S", 1 },
            { "PT2S", 2 },
            { "PT123456789S", 123456789 },
            { "PT+0S", 0 },
            { "PT+2S", 2 },
            { "PT-0S", 0 },
            { "PT-2S", -2 },

            // Minutes.
            { "PT0M", 0 },
            { "PT1M", 60 },
            { "PT2M", 120 },
            { "PT1234M", 1234 * 60 },
            { "PT+0M", 0 },
            { "PT+2M", 120 },
            { "PT-0M", 0 },
            { "PT-2M", -120 },

            // Hours.
            { "PT0H", 0 },
            { "PT1H", 60 * 60 },
            { "PT2H", 120 * 60 },
            { "PT1234H", 1234 * 60 * 60 },
            { "PT+0H", 0 },
            { "PT+2H", 120 * 60 },
            { "PT-0H", 0 },
            { "PT-2H", -120 * 60 },

            // Days.
            { "P0D", 0 },
            { "P1D", 60 * 60 * 24 },
            { "P2D", 120 * 60 * 24 },
            { "P1234D", 1234 * 60 * 60 * 24 },
            { "P+0D", 0 },
            { "P+2D", 120 * 60 * 24 },
            { "P-0D", 0 },
            { "P-2D", -120 * 60 * 24 },

            // Compound minute/second values with independent signs.
            { "PT0M0S", 0 },
            { "PT2M3S", 2 * 60 + 3 },
            { "PT+2M3S", 2 * 60 + 3 },
            { "PT2M+3S", 2 * 60 + 3 },
            { "PT-2M3S", -2 * 60 + 3 },
            { "PT2M-3S", 2 * 60 - 3 },
            { "PT-2M-3S", -2 * 60 - 3 },

            // Compound hour/second values with independent signs.
            { "PT0H0S", 0 },
            { "PT2H3S", 2 * 3600 + 3 },
            { "PT+2H3S", 2 * 3600 + 3 },
            { "PT2H+3S", 2 * 3600 + 3 },
            { "PT-2H3S", -2 * 3600 + 3 },
            { "PT2H-3S", 2 * 3600 - 3 },
            { "PT-2H-3S", -2 * 3600 - 3 },

            // Full period/time combinations.
            { "P0DT0H0M0S", 0 },
            { "P5DT2H4M3S", 5 * 86400 + 2 * 3600 + 4 * 60 + 3 },
        };
    }

    @ParameterizedTest
    @MethodSource("data_valid")
    public void test_parse_CharSequence_valid(String str, int expectedSeconds) {
        assertEquals(Seconds.of(expectedSeconds), Seconds.parse(str));
    }
}
